-- mcp: generated by `npm run guide:content` from content/guide/mcp.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 16,
  "outcome": "Вы подключаете агенту внешние инструменты через MCP — трекер, базу, документацию — с подходящей областью действия и под контролем прав.",
  "blocks": [
    {
      "type": "scene",
      "text": "Каждое утро одно и то же: открыть задачу в трекере, скопировать описание агенту, потом перенести его вопросы обратно в комментарии. Агент не видит ни трекера, ни логов, ни базы — только то, что вы принесли ему руками. Половина работы — быть курьером между окнами."
    },
    {
      "type": "text",
      "text": "MCP (Model Context Protocol) — способ дать агенту инструменты за пределами терминала: задачи из трекера, данные из базы, макеты, документацию. Сервер MCP описывает свои инструменты, а Claude Code вызывает их как собственные."
    },
    {
      "type": "bridge",
      "text": "Вы подключали к IDE плагины для базы, трекера и логов, чтобы не переключаться между окнами. MCP-сервер — такой плагин для агента: он сам видит сервис и обращается к нему через инструменты."
    },
    {
      "type": "why",
      "text": "Агент действует только инструментами: читает файлы, запускает команды. MCP-сервер добавляет к ним новые — «получить задачу», «выполнить запрос», — и агент вызывает их так же, как свои, по тем же правилам доступа. Всё, что вернёт сервер, попадает в окно как текст, поэтому сервер выбирают так же осторожно, как зависимость."
    },
    {
      "type": "command",
      "code": "claude mcp add --transport http tracker https://mcp.example.com/mcp",
      "caption": "Подключение удалённого сервера по HTTP. Локальный подключается через `--transport stdio` и команду запуска после `--`."
