-- git-flow: generated by `npm run guide:content` from content/guide/git-flow.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 15,
  "outcome": "Вы поручаете агенту ветки, коммиты и PR, а решения, которые нельзя откатить, оставляете себе.",
  "blocks": [
    {
      "type": "scene",
      "text": "Агенту разрешили всё, чтобы не отвлекаться на подтверждения. Он закончил фичу, сделал `rebase` на свежий `main` и, чтобы ветка ушла, выполнил `git push --force`. Ветка была общей: два коммита коллеги, сделанные утром, исчезли из истории."
    },
    {
      "type": "text",
      "text": "Рутину git агент делает отлично: создаёт ветку, пишет понятное сообщение коммита, открывает PR с описанием. Ваша часть — всё, что выходит за пределы вашей машины: пуш, слияние, публикация."
    },
    {
      "type": "bridge",
      "text": "В команде вы договаривались о git-процессе: как называть ветки и коммиты, кто сливает в main, что можно делать с общими ветками. Агент — ещё один участник этого процесса, и договорённости для него те же, только записанные в CLAUDE.md и подкреплённые настройками."
    },
    {
      "type": "why",
      "text": "Локальные действия git обратимы: ветку можно удалить, коммит — переписать, пока он только у вас. Пуш, слияние и force push меняют то, что видят другие, и откатить их без чужой помощи трудно. Поэтому граница проходит по краю вашей машины: всё до пуша — агенту, всё после — вам."
    },
    {
      "type": "heading",
      "text": "Что отдать агенту"
    },
    {
      "type": "list",
      "items": [
        "**Ветку под задачу**: «создай ветку fix/promo-rounding от main».",
        "**Коммиты по шагам**: агент пишет сообщение по diff. Формат, принятый в команде, запишите в CLAUDE.md.",
        "**PR**: «создай PR» — агент воспользуется `gh pr create` (для GitLab — `glab`) и опишет изменения.",
        "**Разбор конфликтов** при обновлении ветки — с вашей проверкой результата."
      ]
    },
    {
      "type": "heading",
      "text": "Что оставить себе"
    },
    {
      "type": "list",
      "items": [
        "**Пуш и слияние в main** — если сомневаетесь, запретите правилом `deny` на `Bash(git push *)` (шаг 1.2).",
        "**Переписывание истории**: `git push --force`, `rebase` общих веток.",
        "**Финальное ревью** перед слиянием (шаг 4.1)."
      ]
    },
    {
      "type": "code",
      "file": "CLAUDE.md",
      "code": "## Git\n- Ветки: `fix/…`, `feat/…` от `main`\n- Коммиты: `тип: что сделано`, по-английски, в повелительном наклонении\n- PR: проблема, решение, как проверено; скриншоты для изменений UI\n- Не пушить и не сливать — это делает человек",
      "caption": "Эти соглашения агент повторит в каждом коммите и PR. Последнюю строку подкрепите правилом `deny`."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: агент создаёт ветку, исправляет округление, прогоняет тесты и делает коммит в формате команды. Пуш он оставляет разработчику; после пуша агент открывает PR через gh pr create.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Ветка fix/promo-rounding, исправь округление, коммит в нашем формате.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "git switch -c fix/promo-rounding"
        },
        {
          "kind": "edit",
          "text": "src/cart/total.ts",
          "diff": "+2 −1"
        },
        {
          "kind": "pass",
          "text": "npm test — пройдено"
        },
        {
          "kind": "info",
          "text": "git commit -m \"fix: round promo discounts to kopecks\""
        },
        {
          "kind": "meta",
          "text": "git push — по правилам проекта это делаете вы"
        },
        {
          "kind": "prompt",
          "text": "Запушил. Открой PR.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "gh pr create --title \"fix: round promo discounts to kopecks\""
        },
        {
          "kind": "done",
          "text": "PR открыт: что изменено, почему и как проверено."
        }
      ]
    },
    {
      "type": "spot",
      "title": "Ход агента · четыре команды",
      "prompt": "Агент предлагает четыре команды. Какую вы остановите?",
      "items": [
        {
          "id": "switch",
          "text": "`git switch -c fix/promo-rounding main`"
        },
        {
          "id": "commit",
          "text": "`git commit -m \"fix: round promo discounts to kopecks\"`"
        },
        {
          "id": "amend",
          "text": "`git commit --amend` для своего последнего, ещё не запушенного коммита"
        },
        {
          "id": "force",
          "text": "`git push --force` в общую ветку `release/2.4`"
        }
      ],
      "answer": "force",
      "reveal": "Force push в общую ветку переписывает историю, которую уже забрали коллеги, и их коммиты могут пропасть. Это решение за вами, а надёжнее — правило `deny`. Остальные три команды меняют только вашу локальную копию: их легко откатить."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Сообщение пишет агент, смысл проверяете вы",
      "text": "Агент гладко опишет diff, даже если изменение спорное. Читайте описание PR как отчёт: совпадает ли «что и почему» с тем, что вы просили."
